+/** Stable evidence kinds, ordered by relevance tier (lower is more relevant). */
+type EvidenceKind =
+  | "target"
+  | "structural"
+  | "claim"
+  | "decision"
+  | "conflict"
+  | "intent"
+  | "relationship"
+  | "provenance";
